llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Tofogliflozin showed a mean absolute oral bioavailability of 97.5% in healthy male volunteers using a double tracer technique with a 20 mg oral dose and concomitant IV microdose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Dapagliflozin absolute oral bioavailability was 78% (90% CI 73–83%) in healthy subjects using simultaneous IV 14C-microdose and therapeutic oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Empagliflozin was reported to have an absolute oral bioavailability of 90% in humans.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transferability human absolute bioavailability measurements (97.5%, 78%, 90%) are well above the 20% threshold, supporting high oral bioavailability. Mixed food-effect and predicted records do not outweigh these direct measurements.",
  "evidence_gaps": [
    "Molecule 6 includes didanosine records under emtricitabine; these inconsistent cards were discounted as a provenance conflict.",
    "Molecule 9 is a predicted human oral bioavailability range (20–30%) without direct clinical measurement, adding uncertainty.",
    "Molecule 2 shows food-dependent F with fed values below 20% and fasting values above 20%, so its direction is mixed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

